create extension if not exists "uuid-ossp";
create table if not exists sources(id uuid primary key default uuid_generate_v4(),name text not null,short_name text not null unique,website_url text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists documents(id uuid primary key default uuid_generate_v4(),source_id uuid not null references sources(id) on delete restrict,title text not null,doc_type text not null,publication_date date not null,period_covered text not null,language text not null default 'en',file_hash text not null unique,file_url text,status text not null default 'registered',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists categories(id uuid primary key default uuid_generate_v4(),name text not null,parent_id uuid references categories(id) on delete restrict,created_at timestamptz not null default now());
create table if not exists indicators(id uuid primary key default uuid_generate_v4(),code text not null unique,name text not null,name_ne text,description text,category_id uuid references categories(id) on delete set null,unit text not null,scale text not null default 'units',frequency text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists periods(id uuid primary key default uuid_generate_v4(),type text not null,label text not null,label_ad text not null,start_date date not null,end_date date not null,created_at timestamptz not null default now(),unique(type,label));
